import { useCallback, useState } from "react";
import {
  ReactFlow,
  Controls,
  Background,
  BackgroundVariant,
  addEdge,
  useNodesState,
  useEdgesState,
  Handle,
  Position,
  type Connection,
  type Node,
  type Edge,
  type NodeProps,
  MarkerType,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
// Card not used currently but kept for potential future use
import { fetchWithBaseUrl, fetcher } from "@/lib/utils";
import {
  Clapperboard,
  Clock,
  Hand,
  Home,
  Loader2,
  Play,
  Save,
  Square,
  Target,
  Trash2,
} from "lucide-react";
import { toast } from "sonner";
import useSWR from "swr";

// --- Node data types ---

interface MacroNodeData {
  label: string;
  nodeType: "macro";
  macroName: string;
  speed: number;
  loops: number;
  [key: string]: unknown;
}

interface DelayNodeData {
  label: string;
  nodeType: "delay";
  seconds: number;
  [key: string]: unknown;
}

// HomeNode data follows the same pattern as other nodes: { label, nodeType: "home" }

interface GripperNodeData {
  label: string;
  nodeType: "gripper";
  action: "open" | "close";
  [key: string]: unknown;
}

interface MoveToNodeData {
  label: string;
  nodeType: "moveTo";
  angles: number[];
  [key: string]: unknown;
}



// --- Custom Nodes ---

const nodeColors: Record<string, string> = {
  macro: "#6366f1",
  delay: "#f59e0b",
  home: "#10b981",
  gripper: "#ec4899",
  moveTo: "#3b82f6",
};

function BaseNode({
  children,
  color,
  icon: Icon,
  title,
}: {
  children?: React.ReactNode;
  color: string;
  icon: React.ComponentType<{ className?: string }>;
  title: string;
}) {
  return (
    <div
      className="rounded-lg border shadow-md min-w-[180px] text-xs"
      style={{
        borderColor: color,
        background: "var(--card)",
        color: "var(--card-foreground)",
      }}
    >
      <Handle type="target" position={Position.Top} className="!bg-muted-foreground !w-2.5 !h-2.5" />
      <div
        className="flex items-center gap-1.5 px-3 py-1.5 rounded-t-lg font-semibold text-white text-[11px]"
        style={{ background: color }}
      >
        <Icon className="size-3" />
        {title}
      </div>
      <div className="px-3 py-2 space-y-1.5">{children}</div>
      <Handle type="source" position={Position.Bottom} className="!bg-muted-foreground !w-2.5 !h-2.5" />
    </div>
  );
}

function MacroNode({ data }: NodeProps<Node<MacroNodeData>>) {
  return (
    <BaseNode color={nodeColors.macro} icon={Clapperboard} title="Macro">
      <div className="text-muted-foreground">
        <span className="font-mono text-foreground">{data.macroName || "—"}</span>
      </div>
      <div className="flex gap-2 text-[10px] text-muted-foreground">
        <span>Speed: {data.speed}x</span>
        <span>Loops: {data.loops}</span>
      </div>
    </BaseNode>
  );
}

function DelayNode({ data }: NodeProps<Node<DelayNodeData>>) {
  return (
    <BaseNode color={nodeColors.delay} icon={Clock} title="Delay">
      <div className="text-muted-foreground">
        Wait <span className="font-mono text-foreground">{data.seconds}s</span>
      </div>
    </BaseNode>
  );
}

function HomeNode() {
  return (
    <BaseNode color={nodeColors.home} icon={Home} title="Go Home">
      <div className="text-[10px] text-muted-foreground">Move all joints to zero</div>
    </BaseNode>
  );
}

function GripperNode({ data }: NodeProps<Node<GripperNodeData>>) {
  return (
    <BaseNode color={nodeColors.gripper} icon={Hand} title="Gripper">
      <div className="text-muted-foreground">
        Action: <span className="font-mono text-foreground capitalize">{data.action}</span>
      </div>
    </BaseNode>
  );
}

function MoveToNode({ data }: NodeProps<Node<MoveToNodeData>>) {
  return (
    <BaseNode color={nodeColors.moveTo} icon={Target} title="Move To">
      <div className="font-mono text-[10px] text-muted-foreground">
        [{(data.angles || []).map((a) => a.toFixed(1)).join(", ")}]
      </div>
    </BaseNode>
  );
}

const nodeTypes = {
  macro: MacroNode,
  delay: DelayNode,
  home: HomeNode,
  gripper: GripperNode,
  moveTo: MoveToNode,
};

// --- Helpers ---

let nextId = 1;
function newId() {
  return `node_${Date.now()}_${nextId++}`;
}

function makeNode(type: string, x: number, y: number): Node {
  const id = newId();
  const base = { id, position: { x, y }, type };
  switch (type) {
    case "macro":
      return { ...base, data: { label: "Macro", nodeType: "macro", macroName: "", speed: 1, loops: 1 } };
    case "delay":
      return { ...base, data: { label: "Delay", nodeType: "delay", seconds: 1 } };
    case "home":
      return { ...base, data: { label: "Go Home", nodeType: "home" } };
    case "gripper":
      return { ...base, data: { label: "Gripper", nodeType: "gripper", action: "close" } };
    case "moveTo":
      return { ...base, data: { label: "Move To", nodeType: "moveTo", angles: [0, 0, 0, 0, 0, 0] } };
    default:
      return { ...base, data: { label: type, nodeType: type } };
  }
}

// --- Node palette ---

const nodeTemplates = [
  { type: "macro", label: "Macro", icon: Clapperboard, desc: "Play a recorded macro" },
  { type: "delay", label: "Delay", icon: Clock, desc: "Wait N seconds" },
  { type: "home", label: "Home", icon: Home, desc: "Move to home position" },
  { type: "gripper", label: "Gripper", icon: Hand, desc: "Open/close gripper" },
  { type: "moveTo", label: "Move To", icon: Target, desc: "Move to joint angles" },
];

// --- Main component ---

interface MacroInfo {
  name: string;
  duration_s: number;
  frame_count: number;
}

interface GraphInfo {
  name: string;
  node_count: number;
  edge_count: number;
}

export function SkillGraphPage() {
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [graphName, setGraphName] = useState("untitled");
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const [executing, setExecuting] = useState(false);
  const [saving, setSaving] = useState(false);

  const { data: macroList } = useSWR<{ macros: MacroInfo[] }>("/macro/list", fetcher);
  const { data: graphList, mutate: mutateGraphs } = useSWR<{ graphs: GraphInfo[] }>(
    "/skillgraph/list",
    fetcher,
  );

  const onConnect = useCallback(
    (conn: Connection) =>
      setEdges((eds) =>
        addEdge(
          {
            ...conn,
            animated: true,
            style: { stroke: "var(--border)" },
            markerEnd: { type: MarkerType.ArrowClosed, color: "var(--muted-foreground)" },
          },
          eds,
        ),
      ),
    [setEdges],
  );

  const addNode = useCallback(
    (type: string) => {
      const x = 100 + Math.random() * 200;
      const y = 100 + nodes.length * 80;
      setNodes((nds) => [...nds, makeNode(type, x, y)]);
    },
    [nodes.length, setNodes],
  );

  const deleteSelected = useCallback(() => {
    if (!selectedNode) return;
    setNodes((nds) => nds.filter((n) => n.id !== selectedNode.id));
    setEdges((eds) => eds.filter((e) => e.source !== selectedNode.id && e.target !== selectedNode.id));
    setSelectedNode(null);
  }, [selectedNode, setNodes, setEdges]);

  const updateNodeData = useCallback(
    (nodeId: string, patch: Record<string, unknown>) => {
      setNodes((nds) =>
        nds.map((n) =>
          n.id === nodeId ? { ...n, data: { ...n.data, ...patch } } : n,
        ),
      );
      if (selectedNode?.id === nodeId) {
        setSelectedNode((prev) => prev ? { ...prev, data: { ...prev.data, ...patch } } : prev);
      }
    },
    [setNodes, selectedNode],
  );

  // Save
  async function handleSave() {
    if (!graphName.trim()) { toast.error("Enter a graph name"); return; }
    setSaving(true);
    try {
      const res = await fetchWithBaseUrl("/skillgraph/save", "POST", {
        name: graphName,
        nodes: nodes.map((n) => ({ id: n.id, type: n.type, position: n.position, data: n.data })),
        edges: edges.map((e) => ({ id: e.id, source: e.source, target: e.target })),
      });
      if (res?.status === "ok") {
        toast.success(res.message);
        mutateGraphs();
      }
    } catch { toast.error("Failed to save"); }
    setSaving(false);
  }

  // Load
  async function handleLoad(name: string) {
    try {
      const res = await fetchWithBaseUrl(`/skillgraph/load/${name}`, "GET");
      if (res?.nodes) {
        setNodes(res.nodes);
        setEdges(
          (res.edges || []).map((e: { id: string; source: string; target: string }) => ({
            ...e,
            animated: true,
            style: { stroke: "var(--border)" },
            markerEnd: { type: MarkerType.ArrowClosed, color: "var(--muted-foreground)" },
          })),
        );
        setGraphName(res.name || name);
        setSelectedNode(null);
        toast.success(`Loaded "${name}"`);
      }
    } catch { toast.error("Failed to load graph"); }
  }

  // Delete graph
  async function handleDeleteGraph(name: string) {
    try {
      await fetchWithBaseUrl(`/skillgraph/delete/${name}`, "DELETE");
      toast.success(`Deleted "${name}"`);
      mutateGraphs();
    } catch { toast.error("Failed to delete"); }
  }

  // Execute
  async function handleExecute() {
    if (!graphName.trim()) return;
    setExecuting(true);
    try {
      await handleSave();
      const res = await fetchWithBaseUrl("/skillgraph/execute", "POST", { name: graphName });
      if (res?.status === "ok") toast.success(res.message);
    } catch (e: unknown) { const detail = e instanceof Object && "detail" in e ? (e as { detail: string }).detail : "Execution failed"; toast.error(detail); }
    setExecuting(false);
  }

  // Stop
  async function handleStop() {
    try {
      await fetchWithBaseUrl("/skillgraph/stop", "POST", {});
      toast.success("Execution stopped");
    } catch { toast.error("Failed to stop"); }
    setExecuting(false);
  }

  // Node selection
  const onNodeClick = useCallback((_: React.MouseEvent, node: Node) => {
    setSelectedNode(node);
  }, []);

  const onPaneClick = useCallback(() => setSelectedNode(null), []);

  return (
    <div className="flex h-[calc(100vh-64px)] -mx-6 -my-5">
      {/* Left panel: palette + saved graphs */}
      <div className="w-56 shrink-0 border-r border-border flex flex-col overflow-y-auto">
        <div className="p-3 border-b border-border">
          <div className="text-[10px] font-mono font-medium uppercase tracking-widest text-muted-foreground/50 mb-2">
            Add Nodes
          </div>
          <div className="space-y-1">
            {nodeTemplates.map((t) => (
              <button
                key={t.type}
                onClick={() => addNode(t.type)}
                className="flex items-center gap-2 w-full px-2 py-1.5 rounded-md text-xs text-muted-foreground hover:text-foreground hover:bg-accent/50 transition-colors"
              >
                <div
                  className="size-5 rounded flex items-center justify-center"
                  style={{ background: nodeColors[t.type] }}
                >
                  <t.icon className="size-3 text-white" />
                </div>
                <div className="text-left">
                  <div className="font-medium text-foreground">{t.label}</div>
                  <div className="text-[10px] text-muted-foreground">{t.desc}</div>
                </div>
              </button>
            ))}
          </div>
        </div>

        <div className="p-3 flex-1">
          <div className="text-[10px] font-mono font-medium uppercase tracking-widest text-muted-foreground/50 mb-2">
            Saved Graphs
          </div>
          {graphList?.graphs?.length ? (
            <div className="space-y-1">
              {graphList.graphs.map((g) => (
                <div
                  key={g.name}
                  className="flex items-center gap-1 group"
                >
                  <button
                    onClick={() => handleLoad(g.name)}
                    className="flex-1 text-left px-2 py-1 rounded text-xs text-muted-foreground hover:text-foreground hover:bg-accent/50 transition-colors truncate"
                  >
                    {g.name}
                    <span className="text-[10px] text-muted-foreground/50 ml-1">
                      ({g.node_count}n)
                    </span>
                  </button>
                  <button
                    onClick={() => handleDeleteGraph(g.name)}
                    className="opacity-0 group-hover:opacity-100 p-0.5 rounded hover:bg-destructive/20 transition-all"
                  >
                    <Trash2 className="size-3 text-destructive" />
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-[10px] text-muted-foreground/50">No saved graphs</p>
          )}
        </div>
      </div>

      {/* Center: flow canvas */}
      <div className="flex-1 flex flex-col">
        {/* Toolbar */}
        <div className="flex items-center gap-2 px-4 py-2 border-b border-border shrink-0">
          <Input
            value={graphName}
            onChange={(e) => setGraphName(e.target.value)}
            className="w-40 h-7 text-xs font-mono"
            placeholder="Graph name"
          />
          <Button size="sm" variant="outline" onClick={handleSave} disabled={saving} className="h-7 text-xs">
            {saving ? <Loader2 className="size-3 animate-spin mr-1" /> : <Save className="size-3 mr-1" />}
            Save
          </Button>
          {executing ? (
            <Button size="sm" variant="destructive" onClick={handleStop} className="h-7 text-xs">
              <Square className="size-3 mr-1" />
              Stop
            </Button>
          ) : (
            <Button size="sm" onClick={handleExecute} disabled={nodes.length === 0} className="h-7 text-xs">
              <Play className="size-3 mr-1" />
              Execute
            </Button>
          )}
          {selectedNode && (
            <Button size="sm" variant="ghost" onClick={deleteSelected} className="h-7 text-xs text-destructive ml-auto">
              <Trash2 className="size-3 mr-1" />
              Delete Node
            </Button>
          )}
        </div>

        {/* Canvas */}
        <div className="flex-1">
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onNodeClick={onNodeClick}
            onPaneClick={onPaneClick}
            nodeTypes={nodeTypes}
            fitView
            className="bg-background"
            defaultEdgeOptions={{
              animated: true,
              style: { stroke: "var(--border)" },
            }}
          >
            <Background variant={BackgroundVariant.Dots} gap={20} size={1} color="var(--border)" />
            <Controls className="!bg-card !border-border !shadow-md [&_button]:!bg-card [&_button]:!border-border [&_button]:!text-foreground [&_button:hover]:!bg-accent" />
          </ReactFlow>
        </div>
      </div>

      {/* Right panel: node properties */}
      <div className="w-60 shrink-0 border-l border-border overflow-y-auto">
        <div className="p-3">
          <div className="text-[10px] font-mono font-medium uppercase tracking-widest text-muted-foreground/50 mb-3">
            Properties
          </div>
          {selectedNode ? (
            <NodeProperties
              node={selectedNode}
              macros={macroList?.macros || []}
              onUpdate={(patch) => updateNodeData(selectedNode.id, patch)}
            />
          ) : (
            <p className="text-xs text-muted-foreground/50">
              Select a node to edit its properties. Drag connections between nodes to define execution order.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

// --- Node Properties Panel ---

function NodeProperties({
  node,
  macros,
  onUpdate,
}: {
  node: Node;
  macros: MacroInfo[];
  onUpdate: (patch: Record<string, unknown>) => void;
}) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const data = node.data as Record<string, any>;
  const nodeType = data.nodeType || node.type;

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2">
        <div
          className="size-4 rounded"
          style={{ background: nodeColors[nodeType] || "#666" }}
        />
        <span className="text-sm font-medium capitalize">{nodeType}</span>
      </div>

      {nodeType === "macro" && (
        <>
          <div className="space-y-1">
            <Label className="text-[11px]">Macro</Label>
            <Select value={data.macroName || ""} onValueChange={(v) => onUpdate({ macroName: v })}>
              <SelectTrigger className="h-7 text-xs">
                <SelectValue placeholder="Select macro" />
              </SelectTrigger>
              <SelectContent>
                {macros.map((m) => (
                  <SelectItem key={m.name} value={m.name} className="text-xs">
                    {m.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-1">
            <Label className="text-[11px]">Speed</Label>
            <Input
              type="number"
              step={0.25}
              min={0.25}
              max={4}
              value={data.speed ?? 1}
              onChange={(e) => onUpdate({ speed: parseFloat(e.target.value) || 1 })}
              className="h-7 text-xs"
            />
          </div>
          <div className="space-y-1">
            <Label className="text-[11px]">Loops</Label>
            <Input
              type="number"
              min={1}
              max={100}
              value={data.loops ?? 1}
              onChange={(e) => onUpdate({ loops: parseInt(e.target.value) || 1 })}
              className="h-7 text-xs"
            />
          </div>
        </>
      )}

      {nodeType === "delay" && (
        <div className="space-y-1">
          <Label className="text-[11px]">Seconds</Label>
          <Input
            type="number"
            step={0.5}
            min={0.1}
            max={60}
            value={data.seconds ?? 1}
            onChange={(e) => onUpdate({ seconds: parseFloat(e.target.value) || 1 })}
            className="h-7 text-xs"
          />
        </div>
      )}

      {nodeType === "gripper" && (
        <div className="space-y-1">
          <Label className="text-[11px]">Action</Label>
          <Select value={data.action || "close"} onValueChange={(v) => onUpdate({ action: v })}>
            <SelectTrigger className="h-7 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="open" className="text-xs">Open</SelectItem>
              <SelectItem value="close" className="text-xs">Close</SelectItem>
            </SelectContent>
          </Select>
        </div>
      )}

      {nodeType === "moveTo" && (
        <div className="space-y-1">
          <Label className="text-[11px]">Joint Angles (rad)</Label>
          {["Rotation", "Pitch", "Elbow", "W.Pitch", "W.Roll", "Jaw"].map((name, i) => (
            <div key={name} className="flex items-center gap-1.5">
              <span className="text-[10px] text-muted-foreground w-12 shrink-0">{name}</span>
              <Input
                type="number"
                step={0.1}
                value={(data.angles || [])[i] ?? 0}
                onChange={(e) => {
                  const a = [...(data.angles || [0, 0, 0, 0, 0, 0])];
                  a[i] = parseFloat(e.target.value) || 0;
                  onUpdate({ angles: a });
                }}
                className="h-6 text-[10px] font-mono"
              />
            </div>
          ))}
        </div>
      )}

      {nodeType === "home" && (
        <p className="text-[11px] text-muted-foreground">
          Moves all joints to 0 rad (home position). No configuration needed.
        </p>
      )}
    </div>
  );
}
